SET NOCOUNT ON; SELECT N'FV_POST', (SELECT COUNT(*) FROM sys.tables WHERE schema_id=SCHEMA_ID(N'dbo')), (SELECT COUNT(*) FROM dbo.SchemaVersions), (SELECT COUNT(*) FROM dbo.SchemaVersions WHERE VersionNumber IN(N'1.8.0-CREATE-LOWRISK',N'1.8.0-LOWRISK-DIRECT',N'1.8.0-EXCEL-CANONICAL-STATUS')), (SELECT COUNT(*) FROM sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1), (SELECT COUNT(*) FROM sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1), (SELECT COUNT(*) FROM sys.triggers tr LEFT JOIN sys.sql_modules m ON m.object_id=tr.object_id WHERE tr.parent_class=1 AND tr.is_ms_shipped=0 AND (tr.is_disabled=1 OR m.definition IS NULL));
